def colour_slug(s):
    s = s.lower()
    for a, b in (("á", "a"), ("é", "e"), ("í", "i"), ("ó", "o"), ("ú", "u"), ("ñ", "n")):
        s = s.replace(a, b)
    return re.sub(r"[^a-z0-9]+", "-", s).strip("-")


FEATURED = {"tribal-panel-set", "halo-airbrush-set", "script-zip-set", "paddock-fleece-set", "thorn-crystal-set",
            "mask-zip-hoodie", "paddock-racing-pant", "marble-saint-pant", "xray-heart-tee", "spray-tribal-polo",
            "ice-puffer", "pyramid-belt"}
BADGES = {"tribal-panel-set": "Top", "mask-zip-hoodie": "Top", "paddock-racing-pant": "Top", "script-zip-set": "Top"}

products = []
for i, (slug, name, cat, price, model, cname, hexv, kind, comp, fit, desc, details, garment, pose) in enumerate(P):
    cs = colour_slug(cname)
    if kind == "jewellery":
        sizes = RINGS if "ring" in slug or "signet" in slug else ONE
    elif kind == "accessory":
        sizes = ONE
    else:
        sizes = WAIST if cat == "pantalones" else TOPS
    products.append({
        "slug": slug, "name": name, "category": cat, "price": price, "sizes": sizes, "model": model,
        "description": desc, "details": details, "composition": comp, "fit": fit, "unisex": True,
        "badge": BADGES.get(slug, "Nuevo" if i % 5 == 0 else None), "featured": slug in FEATURED,
        "kind": kind, "line": "2026", "batch": "ABCD"[i % 4],
        "prompt": {"garment": garment, "back": "", "detail": "", "pose": pose},
        "colors": [{"name": cname, "slug": cs, "hex": hexv, "variant": None,
                    "images": [f"/products/{slug}/{cs}-1.jpg", f"/products/{slug}/{cs}-2.jpg"]}],
    })

catalog = {"categories": [{"slug": s, "name": n} for s, n in CATEGORIES], "models": MODELS, "products": products}
os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, "w", encoding="utf-8") as f:
    json.dump(catalog, f, ensure_ascii=False, indent=2)

